INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62644390', 62644390, 'analyze_legacy', 'Provinsi Jawa Barat', 'provinsi', 'Dinas Ketahanan Pangan dan Peternakan', 'Belanja Jasa Tenaga Kebersihan', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Barat, Bandung (Kota)', 647368632, 'December 2025', 'APBD', 1, 1, '1 Tahun', 'Ruang lingkup Pekerjaan Jasa Tenaga Kebersihan pada Kegiatan Penyediaan Jasa Penunjang Urusan Pemerintahan Daerah Sub Kegiatan Penyediaan Jasa Pelayanan Umum Kantor Dinas Ketahanan Pangan dan Peternakan Provinsi Jawa Barat, meliputi : Seluruh gedung yang ada pada Dinas Ketahanan Pangan dan Peternakan Provinsi Jawa Barat yaitu sebanyak 2 gedung dan halaman/taman. Area Luasan pekerjaan tersebut untuk pembersihan lobi, ruang kerja, ruang kelas, ruang rapat, selasar, teras, toilet, pantry tiap gedung dan pembersihan halaman parkir serta pembuangan sampah ke luar area kantor. Ruang lingkup kerja antara lain sebagai berikut : 1. Pembersihan area ruangan kerja, raung rapat dan ruang kelas meliputi Meubelair peralatan kantor, dinding sekat/partisi, pintu, jendela, langit-langit dan balkon luar ruang kerja termasuk pembuangan sampah. 2. Pembersihan dapur dan toilet/kamar mandi/WC pimpinan meliputi : Lantai, dinding, Wastafel, cermin, urinoir, kloset, saluran air kotor, jendela, pintu dan langit-langit. 3. Selasar teras balkon luar. 4. Pembersih ruang kerja tambahan. 5. Pembersih loby, tangga, dinding marmer/keramik, teralis tangga, tempat abu rokok/tempat sampah. 6. Pekerjaan Kebersihan Halaman meliputi : • Kebersihan Halaman. • Kebersihan saluran air • Kebersihan tempat parkir mobil dan motor • Pembuangan/pengangkutan sampah. • Pemeliharaan Taman • Pemotongan rumput', 'Tenaga Kebersihan sebanyak 8 (delapan) orang, persyaratan Personil sebagai berikut : - Minimal lulusan SMP. - Usia 20 - 45 Tahun. - Memiliki SIM A - Berpengalaman minimal 1 tahun. - Lulus seleksi oleh Vendor dan Proses Training. - Bebas Narkoba, dibuktikan dengan Hasil Uji Laboratorium dan masih berlaku; - Melampirkan Surat Keterangan Sehat dari Instansi yang berwenang yang masih berlaku; - Tidak terlibat (Ormas/Organisasi terlarang).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 710485);
