INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62503489', 62503489, 'analyze_legacy', 'Mahkamah Agung', 'central', 'PENGADILAN AGAMA CIBINONG01', 'Petugas Kebersihan', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Barat, Bogor (Kab.)', 147303000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 39, OB, @ 3777000 )', '1. Petugas Kebersihan ( 39, OB, @ 3777000 );', 'Pengadaan ini merupakan belanja jasa lainnya berupa penyediaan tenaga petugas kebersihan melalui mekanisme alih daya (outsourcing) untuk mendukung kelancaran operasional, administrasi perkantoran, dan pelayanan publik di Pengadilan Agama Cibinong. 1. Ruang Lingkup Pekerjaan - Penyediaan tenaga petugas kebersihan sesuai kebutuhan satuan kerja sebanyak 3 (tiga) orang/personel selama masa kontrak; Pelaksanaan tugas petugas kebersihan antara lain: > Menjaga kebersihan dan kerapian ruang kerja, ruang pelayanan, ruang sidang, serta area pendukung lainnya; >Membantu penyiapan ruang sidang dan kegiatan kedinasan; > Membantu kegiatan operasional perkantoran sehari-hari; > Membantu pendistribusian dokumen dan perlengkapan kantor; > Melaksanakan tugas lain yang relevan sesuai kebutuhan satuan kerja. 2. Jam Kerja Jam kerja mengikuti ketentuan jam kerja yang berlaku di Pengadilan Agama Cibinong. 3. Pengelolaan Tenaga Kerja - Penyedia bertanggung jawab atas rekrutmen, pengawasan, pembinaan, dan penggantian tenaga kerja apabila diperlukan; - Penyedia memberikan garansi minimal 3 (tiga) kali dalam 1 (satu) tahun untuk evaluasi kinerja personel dan bersedia melakukan penggantian personel apabila memperoleh hasil evaluasi yang tidak memenuhi standar; - Penyedia memberikan jaminan perlindungan tenaga kerja, antara lain BPJS Ketenagakerjaan, BPJS Kesehatan, THR Keagamaan, serta hak-hak lain sesuai ketentuan peraturan perundang-undangan. 4. Peralatan dan Seragam Penyedia menyediakan seragam kerja dan perlengkapan pendukung yang diperlukan dalam pelaksanaan tugas. 5. Standar Layanan (SLA) - Kehadiran tenaga kerja minimal 95% dari hari kerja dalam 1 (satu) bulan; - Penggantian tenaga kerja yang berhalangan tetap dilakukan paling lambat 1 x 24 jam; - Tenaga kerja wajib bersikap sopan, disiplin, bertanggung jawab, serta menjaga etika dan kerahasiaan dokumen pengadilan. 6. Masa Layanan - Layanan diberikan selama masa kontrak sesuai Tahun Anggaran berjalan. 7. Ketentuan Lain - Seluruh pekerjaan dilaksanakan sesuai ketentuan peraturan perundang-undangan di bidang pengadaan barang/jasa dan ketenagakerjaan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 712460);
