INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62615500', 62615500, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'DINAS PENDIDIKAN', 'Jasa Konsultansi Penyediaan Tenaga Ahli Pengaduan Masyarakat', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 122100000, 'December 2025', 'APBD', 1, 1, '1 Orang x 12 Bulan', 'Memberikan pelayanan pengaduan Masyarakat yang ditujukan ke PPID Dinas Pendidikan Provinsi DKI Jakarta yang masuk melalui permohonan secara langsung (offline) dan tidak langsung (online); Menganalisa dan memverifikasi pengaduan masyarakat yang diterima valid dan dapat diproses lebih lanjut oleh PPID Dinas Pendidikan Provinsi DKI Jakarta; Mengumpulkan dan mengklasifikasi pengaduan masyarakat dari Dinas Pendidikan, Suku Dinas Pendidikan, UPT, dan Satuan Pendidikan; Menganalisa dan menyusun jawaban pengaduan masyarakat bersama tim PPID Dinas Pendidikan Provinsi DKI Jakarta untuk dikirimkan kepada pemohon pengaduan masyarakat; Melaksanakan Forum Komunikasi PPID/Bimbingan Teknis kepada seluruh petugas data dan informasi PPID pada Dinas Pendidikan, Suku Dinas Pendidikan, UPT, dan Satuan Pendidikan untuk meningkatkan pemahaman dan kemampuan teknis mengenai pengelolaan pengaduan masyarakat; Melakukan koordinasi dengan berbagai pihak internal dan eksternal, untuk mencari solusi atau jawaban atas pengaduan masyarakat; Memastikan bahwa setiap pengaduan Masyarakat yang telah ditindaklanjuti diproses hingga selesai; Membantu menyusun atau memperbarui SOP terkait dengan penanganan pengaduan Masyarakat untuk memastikan bahwa seluruh proses berjalan dengan efektif dan efisien; dan Monitoring dan evaluasi pelayanan pengaduan masyarakat yang dilaksanakan oleh PPID Dinas Pendidikan Provinsi DKI Jakarta.', 'Tenaga Ahli Tidak Ber SKA / SKK Spesifikasi: S1 Pengalaman Minimal 3 Tahun (Jasa Konsultansi Perorangan Non Konstruksi)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 713426);
