INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63174988', 63174988, 'analyze_legacy', 'Kementerian Kelautan Dan Perikanan', 'central', 'STASIUN KARANTINA IKAN PENGENDALIAN MUTU DAN KEAMANAN HASIL PERIKANAN BANDUNG', 'Belanja Barang Persediaan bahan baku', 'Barang', 'Pengadaan Langsung', 'Jawa Barat, Cimahi (Kota)', 16000000, 'August 2026', 'APBN - PNBP (D)', 0, 0, '1 Paket', '1. Bahan Uji Laboratorium Bandung ( 1, PKT, @ 16000000 );', '1. Lingkup Pekerjaan • Nama Paket: Pengadaan Bahan Habis Pakai (Reagen dan Test Kit) Laboratorium. • Volume: 1 Paket (Terdiri dari 6 item komoditas). • Total Pagu: Rp16.000.000,-. • Tujuan: Mendukung kegiatan pengujian mikrobiologi dan kimia di Laboratorium Bandung selama tahun 2026. 2. Rincian Teknis Barang 3 Plate Count Agar (PCA), Himedia M091-500G 1 Ammonium Chloride, Millipore/Merck 1.01145.0500 (500 gr) 1 Asam Trichloroasetat 200 ml, Merck 1.00807.0250 1 Chlorine Test Kit, Hydrion 2 Formalin Test Kits, Merck 1.08128.0001 2 XLD Agar (Xylose Lysine Deoxycholate), Himedia M031-100G 3. Persyaratan Khusus Barang • Masa Kedaluwarsa (Expiry Date): Minimal 18-24 bulan saat barang diterima di Laboratorium Bandung (Mengingat penggunaan untuk sepanjang tahun 2026). • Sertifikat Analisis (CoA): Penyedia wajib melampirkan Certificate of Analysis (CoA) dan Material Safety Data Sheet (MSDS) untuk setiap nomor lot barang yang dikirim. • Kondisi Fisik: Botol/kemasan harus tersegel asli dari manufaktur (Merck/Millipore/Himedia/Hydrion), tidak cacat, dan label terbaca jelas. 4. Mekanisme Pengiriman dan Penyerahan • Lokasi: Penyerahan dilakukan di gudang/laboratorium pemesan di Bandung. • Transportasi: Bahan kimia cair atau sensitif harus dikemas menggunakan pengaman tambahan (bubble wrap/peti kayu) untuk mencegah kebocoran selama pengiriman. • Waktu Penyerahan: Maksimal 30 hari kalender setelah SPK diterbitkan (atau sesuai ketersediaan stok impor). 5. Ketentuan Pembayaran dan Pajak • Nilai Kontrak: Rp16.000.000,- sudah termasuk PPN 12% (Tarif pajak tahun 2026) dan biaya kirim ke Bandung. • Sistem Pembayaran: Pembayaran dilakukan sekaligus setelah seluruh barang diperiksa dan dinyatakan sesuai melalui Berita Acara Serah Terima (BAST).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 719591);
